{
  "name": "RecaptchaInterop",
  "version": "101.0.0",
  "summary": "Interfaces that allow Firebase SDKs to use RecaptchaEnterprise functionality.",
  "description": "Not for public use.\nA set of protocols that Firebase SDKs can use to interoperate with RecaptchaEnterprise in a safe\nand reliable manner.",
  "homepage": "https://cloud.google.com/recaptcha-enterprise",
  "license": {
    "type": "Apache-2.0",
    "file": "LICENSE"
  },
  "authors": "Google, Inc.",
  "source": {
    "git": "https://github.com/google/interop-ios-for-google-sdks.git",
    "tag": "CocoaPods-101.0.0"
  },
  "platforms": {
    "ios": "11.0"
  },
  "source_files": "RecaptchaEnterprise/RecaptchaInterop/**/*.[hm]",
  "public_header_files": "RecaptchaEnterprise/RecaptchaInterop/Public/RecaptchaInterop/*.h"
}
